import sys

MOD = 998244353

def generate_binomial(n):
    binomial = [[0] * (n + 1) for _ in range(n + 1)]
    for i in range(n + 1):
        binomial[i][0] = 1
        for j in range(1, i + 1):
            binomial[i][j] = (binomial[i - 1][j - 1] + binomial[i - 1][j]) % MOD
    return binomial

def mod_pow(base, exp):
    res = 1
    b = base
    e = exp
    while e > 0:
        if e & 1:
            res = (res * b) % MOD
        b = (b * b) % MOD
        e >>= 1
    return res

def main():
    input_line = sys.stdin.readline().strip().split()
    n, k, l = map(int, input_line)
    binomial = generate_binomial(n)
    p = [0] * (2 * n + 1)
    q = [0] * (2 * n + 1)
    a = [0] * (2 * n + 1)

    p[n] = mod_pow(2, n)
    for _ in range(n):
        for j in range(2 * n, 0, -1):
            p[j] = (p[j] - p[j - 1]) % MOD

    for j in range(2 * n + 1):
        a[j] = p[j]

    inv2 = (MOD + 1) // 2
    for i in range(1, n - k + 1):
        for j in range(2 * n):
            q[j] = (p[j + 1] * inv2) % MOD
        q[2 * n] = 0
        for j in range(1, 2 * n + 1):
            q[j] = (q[j] + q[j - 1]) % MOD
        for j in range(2 * n + 1):
            p[j] = (q[j] - p[j]) % MOD
        c = binomial[n][i]
        for j in range(2 * n + 1):
            a[j] = (a[j] + c * p[j]) % MOD

    result = 0
    inv = mod_pow(0, MOD - 2)  # placeholder, will compute per j
    for i in range(2 * n + 1):
        inv = mod_pow(i + 1, MOD - 2)
        result = (result + a[i] * inv) % MOD
    result = (result * l) % MOD
    print(result)

if __name__ == "__main__":
    main()

